Plan for this round: the bottle VLA placed nothing (budget exhausted while holding it high). So I'll switch the bottle to a hybrid: a VLA **pick** step, then `MoveSkill` waypoints that place the bottle on the rack using the live gripper↔bottle offset (`scene.eef - scene.pos(bottle)`), then open and retreat. Bowl stays a VLA step, stove-on stays a VLA step and runs last (so the stove is cold while the arm works near the table).

```python
# file: cook_setup.py
from kitchen import *

VERSION = 2

RACK_TOP_Z = 0.920

# ---------------- checks ----------------

class BowlOnStove(Check):
    def ok(self, scene):
        return scene.holds("on", "akita_black_bowl_1", "flat_stove_1_cook_region")

class BottleOnRack(Check):
    def ok(self, scene):
        return scene.holds("on", "wine_bottle_1", "wine_rack_1_top_region")

class BottleHeld(Check):
    def ok(self, scene):
        return scene.gripper_width < 0.05 and scene.pos("wine_bottle_1")[2] > 0.95

class StoveOn(Check):
    def ok(self, scene):
        return scene.holds("turnon", "flat_stove_1")

# ---------------- VLA steps ----------------

class BowlToStove(VLASkill):
    INSTRUCTION = "put the black bowl on the stove"
    MAX_STEPS = 300

    def done(self, scene):
        return scene.holds("on", "akita_black_bowl_1", "flat_stove_1_cook_region")

class BottlePick(VLASkill):
    INSTRUCTION = "pick up the wine bottle"
    MAX_STEPS = 200

    def done(self, scene):
        return scene.pos("wine_bottle_1")[2] > 0.95

class TurnOnStove(VLASkill):
    INSTRUCTION = "turn on the stove"
    MAX_STEPS = 200

    def done(self, scene):
        return scene.holds("turnon", "flat_stove_1")

# ---------------- geometric place on the rack ----------------

class _RackMove(MoveSkill):
    """Move so that the *bottle base* ends up at a wanted height on the rack.

    The gripper holds the bottle with a constant offset d = eef - bottle_base,
    measured once at the start of this move.  We keep the orientation, so d
    stays valid for the whole motion.
    """
    TOL = 0.02
    MAX_STEPS = 80
    Z_EXTRA = 0.0
    _d = None

    def target(self, scene):
        b = scene.pos("wine_bottle_1")
        e = scene.eef
        if _RackMove._d is None:
            _RackMove._d = [e[0] - b[0], e[1] - b[1], e[2] - b[2]]
        d = _RackMove._d
        rt = scene.pos("wine_rack_1")
        return ([rt[0] + d[0], rt[1] + d[1], RACK_TOP_Z + d[2] + self.Z_EXTRA], 1)

class RackAbove(_RackMove):
    Z_EXTRA = 0.12          # first go above the rack, bottle clear of it

class RackPlace(_RackMove):
    Z_EXTRA = 0.02          # lower the bottle base just above the rack top

class OpenGrip(Gripper):
    GRIP = -1

class RackRetreat(MoveSkill):
    TOL = 0.02
    MAX_STEPS = 60

    def target(self, scene):
        e = scene.eef
        return ([e[0], e[1], e[2] + 0.10], -1)

# ---------------- tree ----------------

def build():
    return Sequence(
        Fallback(Leaf("bowl_on_stove"), Leaf("bowl_to_stove")),
        Fallback(
            Leaf("bottle_on_rack"),
            Sequence(
                Fallback(Leaf("bottle_held"), Leaf("bottle_pick")),
                Leaf("rack_above"),
                Leaf("rack_place"),
                Leaf("open_grip"),
                Leaf("rack_retreat"),
            ),
        ),
        Fallback(Leaf("stove_on"), Leaf("turn_on_stove")),
    )

# ---------------- registration ----------------

def apply(ctx, config):
    yield ctx.registry.register("bowl_on_stove", VERSION, BowlOnStove)
    yield ctx.registry.register("bottle_on_rack", VERSION, BottleOnRack)
    yield ctx.registry.register("bottle_held", VERSION, BottleHeld)
    yield ctx.registry.register("stove_on", VERSION, StoveOn)

    yield ctx.registry.register("bowl_to_stove", VERSION, BowlToStove)
    yield ctx.registry.register("bottle_pick", VERSION, BottlePick)
    yield ctx.registry.register("turn_on_stove", VERSION, TurnOnStove)

    yield ctx.registry.register("rack_above", VERSION, RackAbove)
    yield ctx.registry.register("rack_place", VERSION, RackPlace)
    yield ctx.registry.register("open_grip", VERSION, OpenGrip)
    yield ctx.registry.register("rack_retreat", VERSION, RackRetreat)

    yield ctx.registry.register("main", VERSION, build)
```

Plan v3: split each task into a VLA **pick** (which worked in run 1 for the bottle) plus a *geometric* `MoveSkill` place, so the failure point (placing on the rack/cook region) is no longer left to the policy. The grasp offset `d = eef − object_base` is measured at runtime while held, so the place lands the **object base** (not the gripper) on the target surface. Bowl first, then bottle, then turn the stove on last (stove cold during all nearby motion).

```python
# file: cook_setup.py
from kitchen import *

VERSION = 3

COOK_X, COOK_Y, COOK_Z = -0.254, 0.202, 0.905
RACK_X, RACK_Y, RACK_Z = -0.267, -0.251, 0.920

# ---------------- checks ----------------

class BowlOnStove(Check):
    def ok(self, scene):
        return scene.holds("on", "akita_black_bowl_1", "flat_stove_1_cook_region")

class BottleOnRack(Check):
    def ok(self, scene):
        return scene.holds("on", "wine_bottle_1", "wine_rack_1_top_region")

class StoveOn(Check):
    def ok(self, scene):
        return scene.holds("turnon", "flat_stove_1")

def _held(scene, obj):
    if scene.gripper_width > 0.06:
        return False
    e = scene.eef
    p = scene.pos(obj)
    return (abs(e[0] - p[0]) < 0.15 and abs(e[1] - p[1]) < 0.15
            and abs(e[2] - p[2]) < 0.30)

class BowlHeld(Check):
    def ok(self, scene):
        return _held(scene, "akita_black_bowl_1")

class BottleHeld(Check):
    def ok(self, scene):
        return _held(scene, "wine_bottle_1")

# ---------------- VLA picks ----------------

class BowlPick(VLASkill):
    INSTRUCTION = "pick up the black bowl"
    MAX_STEPS = 150

    def done(self, scene):
        return _held(scene, "akita_black_bowl_1")

class BottlePick(VLASkill):
    INSTRUCTION = "pick up the wine bottle"
    MAX_STEPS = 150

    def done(self, scene):
        return _held(scene, "wine_bottle_1")

class TurnOnStove(VLASkill):
    INSTRUCTION = "turn on the stove"
    MAX_STEPS = 200

    def done(self, scene):
        return scene.holds("turnon", "flat_stove_1")

# ---------------- geometric place ----------------

class _PlaceMove(MoveSkill):
    """Move so the held object's BASE goes to (TX, TY, TZ + DZ).

    The offset d = eef - object_base is fixed while the grasp holds, and is
    measured once per subclass at the start of the motion.
    """
    OBJ = None
    TX = 0.0
    TY = 0.0
    TZ = 0.0
    DZ = 0.0
    GRIP = 1
    TOL = 0.02
    MAX_STEPS = 100

    def target(self, scene):
        cls = type(self)
        p = scene.pos(self.OBJ)
        e = scene.eef
        if cls.__dict__.get("_d") is None:
            cls._d = [e[0] - p[0], e[1] - p[1], e[2] - p[2]]
        d = cls._d
        return ([self.TX + d[0], self.TY + d[1], self.TZ + self.DZ + d[2]],
                self.GRIP)

class BowlAbove(_PlaceMove):
    OBJ = "akita_black_bowl_1"
    TX, TY, TZ = COOK_X, COOK_Y, COOK_Z
    DZ = 0.12

class BowlDown(_PlaceMove):
    OBJ = "akita_black_bowl_1"
    TX, TY, TZ = COOK_X, COOK_Y, COOK_Z
    DZ = 0.005

class BottleAbove(_PlaceMove):
    OBJ = "wine_bottle_1"
    TX, TY, TZ = RACK_X, RACK_Y, RACK_Z
    DZ = 0.12

class BottleDown(_PlaceMove):
    OBJ = "wine_bottle_1"
    TX, TY, TZ = RACK_X, RACK_Y, RACK_Z
    DZ = 0.005

class OpenGrip(Gripper):
    GRIP = -1

class Retreat(MoveSkill):
    GRIP = -1
    TOL = 0.02
    MAX_STEPS = 60

    def target(self, scene):
        e = scene.eef
        return ([e[0], e[1], e[2] + 0.12], -1)

# ---------------- behavior tree ----------------

def build():
    return Sequence(
        # bowl onto the stove cook region
        Fallback(
            Leaf("bowl_on_stove"),
            Sequence(
                Fallback(Leaf("bowl_held"), Leaf("bowl_pick")),
                Leaf("bowl_above"),
                Leaf("bowl_down"),
                Leaf("open_grip"),
                Leaf("retreat"),
            ),
        ),
        # bottle onto the wine rack top
        Fallback(
            Leaf("bottle_on_rack"),
            Sequence(
                Fallback(Leaf("bottle_held"), Leaf("bottle_pick")),
                Leaf("bottle_above"),
                Leaf("bottle_down"),
                Leaf("open_grip"),
                Leaf("retreat"),
            ),
        ),
        # finally light the stove
        Fallback(Leaf("stove_on"), Leaf("turn_on_stove")),
    )

# ---------------- registration ----------------

def apply(ctx, config):
    yield ctx.registry.register("bowl_on_stove", VERSION, BowlOnStove)
    yield ctx.registry.register("bottle_on_rack", VERSION, BottleOnRack)
    yield ctx.registry.register("stove_on", VERSION, StoveOn)
    yield ctx.registry.register("bowl_held", VERSION, BowlHeld)
    yield ctx.registry.register("bottle_held", VERSION, BottleHeld)

    yield ctx.registry.register("bowl_pick", VERSION, BowlPick)
    yield ctx.registry.register("bottle_pick", VERSION, BottlePick)
    yield ctx.registry.register("turn_on_stove", VERSION, TurnOnStove)

    yield ctx.registry.register("bowl_above", VERSION, BowlAbove)
    yield ctx.registry.register("bowl_down", VERSION, BowlDown)
    yield ctx.registry.register("bottle_above", VERSION, BottleAbove)
    yield ctx.registry.register("bottle_down", VERSION, BottleDown)
    yield ctx.registry.register("open_grip", VERSION, OpenGrip)
    yield ctx.registry.register("retreat", VERSION, Retreat)

    yield ctx.registry.register("main", VERSION, build)
```

Diagnosis: the run 3 "pick" was a false positive — my `_held` check (width<0.06, xy<0.15, |dz|<0.30) fired while the gripper merely hovered/clamped above the bowl, so the VLA was stopped before grasping, and the geometric "place" then moved an *empty* gripper using a bogus offset. Two fixes: (1) detect the grasp tightly and **record `(eef, obj_pos)` at the contact instant** (the object is still on the table then, so `d = eef − obj_pos` is the true grasp offset), and (2) derive the place pose from that offset and the known cook region (-0.254, 0.202) / the rack top.

```python
# file: cook_setup.py
from kitchen import *

VERSION = 4

BOWL = "akita_black_bowl_1"
BOTTLE = "wine_bottle_1"
BOWL_REGION = "flat_stove_1_cook_region"
BOTTLE_REGION = "wine_rack_1_top_region"

# known from the task description (safety rule) / current scene
BOWL_TARGET = [-0.254, 0.202, 0.905]
BOTTLE_TARGET = [-0.267, -0.251, 0.95]

# grasp offset captured at the moment of contact:  d = eef - object_pos
GRASP = {}


def _region(scene, name, fallback):
    try:
        p = scene.pos(name)
        if p is not None and len(p) >= 3:
            vals = [float(p[0]), float(p[1]), float(p[2])]
            if all(v == v for v in vals):      # not NaN
                return vals
    except Exception:
        pass
    return list(fallback)


def _grasp_ok(scene, obj):
    """Strict contact test: fingers partly closed AND centred on the object."""
    try:
        w = scene.gripper_width
    except Exception:
        return False
    if not (0.008 < w < 0.072):          # not full-open, not closed on air
        return False
    e = scene.eef
    try:
        p = scene.pos(obj)
    except Exception:
        return False
    return (abs(e[0] - p[0]) < 0.06 and abs(e[1] - p[1]) < 0.06
            and abs(e[2] - p[2]) < 0.18)


def _record(obj, scene):
    if obj not in GRASP:
        try:
            GRASP[obj] = (list(scene.eef), list(scene.pos(obj)))
        except Exception:
            pass


# ---------------- checks ----------------

class BowlOnStove(Check):
    def ok(self, scene):
        return scene.holds("on", BOWL, BOWL_REGION)

class BottleOnRack(Check):
    def ok(self, scene):
        return scene.holds("on", BOTTLE, BOTTLE_REGION)

class StoveOn(Check):
    def ok(self, scene):
        return scene.holds("turnon", "flat_stove_1")

class BowlHeld(Check):
    def ok(self, scene):
        if _grasp_ok(scene, BOWL):
            _record(BOWL, scene)
            return True
        return False

class BottleHeld(Check):
    def ok(self, scene):
        if _grasp_ok(scene, BOTTLE):
            _record(BOTTLE, scene)
            return True
        return False


# ---------------- VLA steps ----------------

class BowlPick(VLASkill):
    INSTRUCTION = "pick up the black bowl"
    MAX_STEPS = 200

    def done(self, scene):
        if _grasp_ok(scene, BOWL):
            _record(BOWL, scene)
            return True
        return False

class BottlePick(VLASkill):
    INSTRUCTION = "pick up the wine bottle"
    MAX_STEPS = 200

    def done(self, scene):
        if _grasp_ok(scene, BOTTLE):
            _record(BOTTLE, scene)
            return True
        return False

class TurnOnStove(VLASkill):
    INSTRUCTION = "turn on the stove"
    MAX_STEPS = 200

    def done(self, scene):
        return scene.holds("turnon", "flat_stove_1")


# ---------------- geometric placing ----------------

class _Place(MoveSkill):
    OBJ = None
    REGION = None
    FALLBACK = (0.0, 0.0, 0.0)
    DZ = 0.0
    TOL = 0.02
    MAX_STEPS = 120

    def target(self, scene):
        e0, p0 = GRASP[self.OBJ]                 # captured at contact
        r = _region(scene, self.REGION, self.FALLBACK)
        return ([r[0] + (e0[0] - p0[0]),
                 r[1] + (e0[1] - p0[1]),
                 r[2] + self.DZ + (e0[2] - p0[2])], 1)

class BowlAbove(_Place):
    OBJ, REGION, FALLBACK = BOWL, BOWL_REGION, BOWL_TARGET
    DZ = 0.12

class BowlDown(_Place):
    OBJ, REGION, FALLBACK = BOWL, BOWL_REGION, BOWL_TARGET
    DZ = 0.005

class BottleAbove(_Place):
    OBJ, REGION, FALLBACK = BOTTLE, BOTTLE_REGION, BOTTLE_TARGET
    DZ = 0.14

class BottleDown(_Place):
    OBJ, REGION, FALLBACK = BOTTLE, BOTTLE_REGION, BOTTLE_TARGET
    DZ = 0.005

class OpenGrip(Gripper):
    GRIP = -1

class Retreat(MoveSkill):
    """Lift straight up to a fixed ceiling height (converges, stateless)."""
    TOL = 0.02
    MAX_STEPS = 80

    def target(self, scene):
        e = scene.eef
        return ([e[0], e[1], min(e[2] + 0.12, 1.30)], -1)


# ---------------- behavior tree ----------------

def build():
    return Sequence(
        Fallback(
            Leaf("bowl_on_stove"),
            Sequence(
                Fallback(Leaf("bowl_held"), Leaf("bowl_pick")),
                Leaf("bowl_above"),
                Leaf("bowl_down"),
                Leaf("open_grip"),
                Leaf("retreat"),
                Leaf("bowl_on_stove"),
            ),
        ),
        Fallback(
            Leaf("bottle_on_rack"),
            Sequence(
                Fallback(Leaf("bottle_held"), Leaf("bottle_pick")),
                Leaf("bottle_above"),
                Leaf("bottle_down"),
                Leaf("open_grip"),
                Leaf("retreat"),
                Leaf("bottle_on_rack"),
            ),
        ),
        Fallback(Leaf("stove_on"), Leaf("turn_on_stove")),
    )


# ---------------- registration ----------------

def apply(ctx, config):
    yield ctx.registry.register("bowl_on_stove", VERSION, BowlOnStove)
    yield ctx.registry.register("bottle_on_rack", VERSION, BottleOnRack)
    yield ctx.registry.register("stove_on", VERSION, StoveOn)
    yield ctx.registry.register("bowl_held", VERSION, BowlHeld)
    yield ctx.registry.register("bottle_held", VERSION, BottleHeld)

    yield ctx.registry.register("bowl_pick", VERSION, BowlPick)
    yield ctx.registry.register("bottle_pick", VERSION, BottlePick)
    yield ctx.registry.register("turn_on_stove", VERSION, TurnOnStove)

    yield ctx.registry.register("bowl_above", VERSION, BowlAbove)
    yield ctx.registry.register("bowl_down", VERSION, BowlDown)
    yield ctx.registry.register("bottle_above", VERSION, BottleAbove)
    yield ctx.registry.register("bottle_down", VERSION, BottleDown)
    yield ctx.registry.register("open_grip", VERSION, OpenGrip)
    yield ctx.registry.register("retreat", VERSION, Retreat)

    yield ctx.registry.register("main", VERSION, build)
```

The bowl pick in run 4 clamped on air. My checks were unreliable and the VLA is pose-sensitive, so I'll make the pick geometric and bounded (with the VLA only as a fallback), and derive the place pose from an offset `d = eef − object_pos` measured **at the grasp moment / while held**, relative to the target region's live position. Order: bottle → bowl → stove on (stove must stay cold until the bowl is down, since the gripper would enter the hot zone).

```python
# file: cook_setup.py
from kitchen import *

VERSION = 5

BOWL = "akita_black_bowl_1"
BOTTLE = "wine_bottle_1"
BOWL_REGION = "flat_stove_1_cook_region"
BOTTLE_REGION = "wine_rack_1_top_region"

# fallbacks if scene.pos(<region>) is unavailable
BOWL_FB = [-0.254, 0.202, 0.905]
BOTTLE_FB = [-0.267, -0.251, 0.95]

BOWL_DZ = 0.06      # eef height above the bowl's reported point when grasping
BOTTLE_DZ = 0.10    # same for the bottle

GRASP = {}          # obj -> [dx,dy,dz] = eef - object_pos, valid while held


def _v(p):
    return [float(p[0]), float(p[1]), float(p[2])]


def _objp(scene, obj):
    try:
        return _v(scene.pos(obj))
    except Exception:
        return None


def _regionp(scene, name, fb):
    try:
        p = _v(scene.pos(name))
        if all(x == x for x in p):          # not NaN
            return p
    except Exception:
        pass
    return list(fb)


# ---------------- goal checks ----------------

class BowlOk(Check):
    def ok(self, scene):
        return scene.holds("on", BOWL, BOWL_REGION)


class BottleOk(Check):
    def ok(self, scene):
        return (scene.holds("on", BOTTLE, BOTTLE_REGION) or
                scene.holds("in", BOTTLE, BOTTLE_REGION))


class StoveOn(Check):
    def ok(self, scene):
        return scene.holds("turnon", "flat_stove_1")


# ---------------- grasp check (also records the held offset) ----------------

class _Grasp(Check):
    OBJ = None

    def ok(self, scene):
        p = _objp(scene, self.OBJ)
        try:
            w = scene.gripper_width
        except Exception:
