        p = _objp(scene, BOWL)
        if p is None:
            return False
        r = _regionp(scene, BOWL_REGION, BOWL_FB)
        return (abs(p[0] - r[0]) < 0.12 and abs(p[1] - r[1]) < 0.12
                and 0.88 < p[2] < 1.00)


